const IconComponent = ({
  name,
  size = 24,
  color = "currentColor",
  className,
  style,
  ...props
}: IconProps) => {
  const icon = iconMap[name];
  if (!icon) return null;

  return (
    <svg
      width={size}
      height={size}
      viewBox={icon.viewBox}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      style={style}
      {...props}
    >
      {icon.path(color)}
    </svg>
  );
};

const Icon = memo(IconComponent);
Icon.displayName = "Icon";
export { Icon };

